let running=false, ignitionOn=true, flowOn=true, cutawayOn=true, turbo=false, muffled=false, throttle=0, mixture=50, rpm=0, revKick=0;
let audio=null, audioNodes=null, lastTime=performance.now(), elapsed=0, toastTimer;
function makeNoise(ctx){const buffer=ctx.createBuffer(1,ctx.sampleRate*2,ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;return buffer}
function startAudio(){if(audio)return;const ctx=new AudioContext(), master=ctx.createGain();master.gain.value=.0001;master.connect(ctx.destination);
 const low=ctx.createBiquadFilter();low.type='lowpass';low.frequency.value=1300;low.Q.value=.8;low.connect(master);
 const distortion=ctx.createWaveShaper();const curve=new Float32Array(512);for(let i=0;i<512;i++){const x=i*2/511-1;curve[i]=Math.tanh(x*2.7)}distortion.curve=curve;distortion.oversample='2x';distortion.connect(low);
 const mix=ctx.createGain();mix.gain.value=.8;mix.connect(distortion);
 const fundamental=ctx.createOscillator();fundamental.type='sawtooth';fundamental.frequency.value=32;const engineGain=ctx.createGain();engineGain.gain.value=.3;fundamental.connect(engineGain);engineGain.connect(mix);fundamental.start();
 const sub=ctx.createOscillator();sub.type='triangle';sub.frequency.value=16;const subGain=ctx.createGain();subGain.gain.value=.5;sub.connect(subGain);subGain.connect(mix);sub.start();
 const harmonics=[];for(const [mul,gain] of [[2,.19],[3,.095],[4,.05]]){const o=ctx.createOscillator(),g=ctx.createGain();o.type='sawtooth';o.frequency.value=32*mul;g.gain.value=gain;o.connect(g);g.connect(mix);o.start();harmonics.push({o,mul})}
 const noise=ctx.createBufferSource();noise.buffer=makeNoise(ctx);noise.loop=true;const noiseFilter=ctx.createBiquadFilter();noiseFilter.type='bandpass';noiseFilter.frequency.value=240;noiseFilter.Q.value=.8;const ng=ctx.createGain();ng.gain.value=.07;noise.connect(noiseFilter);noiseFilter.connect(ng);ng.connect(distortion);noise.start();
 const turboOsc=ctx.createOscillator();turboOsc.type='sine';turboOsc.frequency.value=850;const turboFilter=ctx.createBiquadFilter();turboFilter.type='bandpass';turboFilter.frequency.value=2200;turboFilter.Q.value=3;const tg=ctx.createGain();tg.gain.value=0;turboOsc.connect(turboFilter);turboFilter.connect(tg);tg.connect(low);turboOsc.start();
 audio={ctx,master};audioNodes={fundamental,sub,harmonics,engineGain,subGain,noiseFilter,ng,tg,turboOsc,low};
}
function setAudioActive(active){if(active){startAudio();audio.ctx.resume();audioNodes.master?.gain?.setTargetAtTime(.72,audio.ctx.currentTime,.12);audio.master.gain.setTargetAtTime(.72,audio.ctx.currentTime,.12);$('#soundIndicator').classList.add('active');$('#soundText').textContent='AUDIO LIVE'}else if(audio){audio.master.gain.setTargetAtTime(.0001,audio.ctx.currentTime,.22);$('#soundIndicator').classList.remove('active');$('#soundText').textContent='AUDIO STANDBY'}}
function showToast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
function updateSlider(el,value){const min=+el.min,max=+el.max;el.style.setProperty('--fill',`${(value-min)/(max-min)*100}%`)}
$('#throttle').addEventListener('input',e=>{throttle=+e.target.value;$('#throttleText').textContent=`${throttle}%`;updateSlider(e.target,throttle)});
$('#mixture').addEventListener('input',e=>{mixture=+e.target.value;$('#mixtureText').textContent=mixture<42?'LEAN':mixture>58?'RICH':'STOICH';updateSlider(e.target,mixture)});
updateSlider($('#throttle'),0);updateSlider($('#mixture'),50);
$('#startButton').addEventListener('click',()=>{if(!ignitionOn){ignitionOn=true;showToast('IGNITION ON — START ENGINE TO BEGIN');$('#engineStatus span').textContent='IGNITION READY';$('#engineStatus').classList.remove('running');return}running=!running;if(running){setAudioActive(true);rpm=Math.max(rpm,760);$('#startButton').classList.add('running');$('#startButton').innerHTML='<span class="icon">■</span>STOP ENGINE';$('#engineStatus span').textContent='ENGINE RUNNING';$('#engineStatus').classList.add('running')}else{$('#startButton').classList.remove('running');$('#startButton').innerHTML='<span class="icon">▶</span>START ENGINE';$('#engineStatus span').textContent='ENGINE OFFLINE';$('#engineStatus').classList.remove('running');throttle=0;$('#throttle').value=0;$('#throttleText').textContent='0%';updateSlider($('#throttle'),0);setAudioActive(false)}});
$('#ignition').addEventListener('click',()=>{ignitionOn=!ignitionOn;if(!ignitionOn&&running)$('#startButton').click();if(!ignitionOn){$('#engineStatus span').textContent='IGNITION OFF';showToast('IGNITION CIRCUIT DISABLED')}else{$('#engineStatus span').textContent='IGNITION READY';showToast('IGNITION CIRCUIT ARMED')}});
$('#revButton').addEventListener('click',()=>{if(!running){showToast('START ENGINE TO REV');return}revKick=1;throttle=Math.max(throttle,28);$('#throttle').value=throttle;$('#throttleText').textContent=`${throttle}%`;updateSlider($('#throttle'),throttle);setTimeout(()=>{if(running){throttle=0;$('#throttle').value=0;$('#throttleText').textContent='0%';updateSlider($('#throttle'),0)}},780)});
$$('[data-exhaust]').forEach(b=>b.addEventListener('click',()=>{$$('[data-exhaust]').forEach(x=>x.classList.toggle('active',x===b));muffled=b.dataset.exhaust==='muffled';$('#exhaustText').textContent=muffled?'MUFFLED':'OPEN';if(audio)audioNodes.low.frequency.setTargetAtTime(muffled?520:1300,audio.ctx.currentTime,.2)}));
$$('[data-induction]').forEach(b=>b.addEventListener('click',()=>{$$('[data-induction]').forEach(x=>x.classList.toggle('active',x===b));turbo=b.dataset.induction==='turbo';$('#inductionText').textContent=turbo?'TURBO':'NATURAL';$('#boostSpec').textContent=turbo?'1.8 BAR':'1.0 BAR';if(!turbo&&audio)audioNodes.tg.gain.setTargetAtTime(0,audio.ctx.currentTime,.18);showToast(turbo?'TURBOCHARGER ENGAGED':'NATURALLY ASPIRATED')}));
$('#flowToggle').addEventListener('click',e=>{flowOn=!flowOn;e.currentTarget.classList.toggle('on',flowOn);showToast(flowOn?'FLUID FLOW VISUALIZER ON':'FLUID FLOW VISUALIZER OFF')});
$('#cutawayToggle').addEventListener('click',e=>{cutawayOn=!cutawayOn;e.currentTarget.classList.toggle('on',cutawayOn);banks.forEach(b=>b.children.forEach(c=>{if(c.geometry?.type==='CylinderGeometry'&&c.material===aluminum)c.visible=cutawayOn}));showToast(cutawayOn?'CYLINDER CUTAWAY VISIBLE':'CYLINDER CUTAWAY CLOSED')});
$$('[data-view]').forEach(b=>b.addEventListener('click',()=>{const v=b.dataset.view;if(v==='reset'){orbit.theta=.69;orbit.phi=1.13;orbit.radius=8.55}else if(v==='front'){orbit.theta=.05;orbit.phi=1.18;orbit.radius=8.55}else if(v==='top'){orbit.theta=.15;orbit.phi=.35;orbit.radius=9.6}else if(v==='side'){orbit.theta=1.55;orbit.phi=1.18;orbit.radius=8.4}setCamera();$$('[data-view]').forEach(x=>x.classList.toggle('active',x===b))}));

